import type * as Stitches from '@stitches/react';
import { HTMLAttributes } from 'react';
import { config } from '@hexa-ui/theme';

type CSSVariants = Stitches.CSS<typeof config>;

export interface LoadingDotsTypes extends HTMLAttributes<HTMLDivElement> {
  /** Set the component size */
  size?: 'medium' | 'large' | 'xlarge' | 'xxlarge';
  /** Set the component color option */
  color?: 'colorful' | 'mono';
  /** Set data test id */
  dataTestId?: string;
  /** Set aria label for accessibility */
  ariaLabel?: string;
  /** Set css for the component itself, using stitches config */
  css?: CSSVariants;
}
